const normalizeAccountEmail = (value?: string | null) =>
  value?.trim().toLowerCase() ?? '';
const normalizeIdentityText = (value?: string | null) =>
  value?.trim().toLowerCase() ?? '';
const pickNonEmptyWorkspaceValue = (
  preferred?: string | null,
  fallback?: string | null,
) => (preferred?.trim() ? preferred : (fallback?.trim() ?? ''));
const parseWorkspaceTimestamp = (value?: string | null) => {
  if (typeof value !== 'string' || !value.trim()) return Number.NaN;
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : Number.NaN;
};
const preferLocalWorkspaceValue = ({
  localHasExplicitValue,
  remoteHasExplicitValue,
  localTimestamp,
  remoteTimestamp,
}: {
  localHasExplicitValue: boolean;
  remoteHasExplicitValue: boolean;
  localTimestamp: number;
  remoteTimestamp: number;
}) => {
  if (localHasExplicitValue && !remoteHasExplicitValue) return true;
  if (!localHasExplicitValue && remoteHasExplicitValue) return false;
  if (!localHasExplicitValue && !remoteHasExplicitValue) return true;

  if (Number.isFinite(localTimestamp) && Number.isFinite(remoteTimestamp)) {
    return localTimestamp >= remoteTimestamp;
  }

  if (Number.isFinite(localTimestamp)) return true;
  if (Number.isFinite(remoteTimestamp)) return false;

  return true;
};

const hasOwnWorkspaceValue = <K extends keyof Partial<SalonWorkspace>>(
  workspace: Partial<SalonWorkspace> | null | undefined,
  key: K,
) => Boolean(workspace && Object.prototype.hasOwnProperty.call(workspace, key));

const buildWorkspaceComparisonSignature = (
  workspace: Partial<SalonWorkspace> | null | undefined,
  email: string,
) => {
  const normalized = normalizeWorkspace(workspace, email);
  return JSON.stringify({
    id: normalized.id,
    ownerEmail: normalized.ownerEmail,
    salonCode: normalized.salonCode,
    salonName: normalized.salonName,
    salonNameDisplayStyle: normalized.salonNameDisplayStyle,
    salonNameFontVariant: normalized.salonNameFontVariant,
    salonBrandingUpdatedAt: normalized.salonBrandingUpdatedAt,
    businessPhone: normalized.businessPhone,
    additionalPhones: normalized.additionalPhones,
    activityCategory: normalized.activityCategory,
    streetType: normalized.streetType,
    streetName: normalized.streetName,
    streetNumber: normalized.streetNumber,
    city: normalized.city,
    postalCode: normalized.postalCode,
    salonAddress: normalized.salonAddress,
    subscriptionPlan: normalized.subscriptionPlan,
    subscriptionStatus: normalized.subscriptionStatus,
    isInternalTester: normalized.isInternalTester,
    cashSectionDisabled: normalized.cashSectionDisabled,
    autoAcceptBookingRequests: normalized.autoAcceptBookingRequests,
    autoAcceptBookingRequestsUpdatedAt:
      normalized.autoAcceptBookingRequestsUpdatedAt ?? '',
    customerReminderHoursBefore: normalized.customerReminderHoursBefore,
    createdAt: normalized.createdAt,
    updatedAt: normalized.updatedAt,
    trialEndsAt: normalized.trialEndsAt ?? '',
    subscriptionEndsAt: normalized.subscriptionEndsAt ?? '',
    lastBackupAt: normalized.lastBackupAt ?? '',
  });
};

const areWorkspacesEquivalent = (
  currentWorkspace: Partial<SalonWorkspace> | null | undefined,
  nextWorkspace: Partial<SalonWorkspace> | null | undefined,
  email: string,
) =>
  buildWorkspaceComparisonSignature(currentWorkspace, email) ===
  buildWorkspaceComparisonSignature(nextWorkspace, email);

const mergeWorkspacePreservingLocalProfile = ({
  localWorkspace,
  remoteWorkspace,
  email,
  remoteIsAuthoritative = false,
}: {
  localWorkspace: Partial<SalonWorkspace> | null | undefined;
  remoteWorkspace: Partial<SalonWorkspace> | null | undefined;
  email: string;
  remoteIsAuthoritative?: boolean;
}) => {
  const normalizedEmail = normalizeAccountEmail(email);
  const local = normalizeWorkspace(localWorkspace, normalizedEmail);
  const remote = normalizeWorkspace(
    remoteWorkspace,
    normalizeAccountEmail(remoteWorkspace?.ownerEmail ?? normalizedEmail) ||
      normalizedEmail,
  );
  const confirmedBranding = pickSalonBrandingSource(localWorkspace, remoteWorkspace);
  const localAutoAcceptUpdatedAt = parseWorkspaceTimestamp(
    localWorkspace?.autoAcceptBookingRequestsUpdatedAt,
  );
  const remoteAutoAcceptUpdatedAt = parseWorkspaceTimestamp(
    remoteWorkspace?.autoAcceptBookingRequestsUpdatedAt ??
      remoteWorkspace?.updatedAt,
  );
  const preferLocalAutoAccept = remoteIsAuthoritative
    ? false
    : preferLocalWorkspaceValue({
        localHasExplicitValue:
          hasOwnWorkspaceValue(localWorkspace, 'autoAcceptBookingRequests') &&
          typeof localWorkspace?.autoAcceptBookingRequests === 'boolean',
        remoteHasExplicitValue:
          hasOwnWorkspaceValue(remoteWorkspace, 'autoAcceptBookingRequests') &&
          typeof remoteWorkspace?.autoAcceptBookingRequests === 'boolean',
        localTimestamp: localAutoAcceptUpdatedAt,
        remoteTimestamp: remoteAutoAcceptUpdatedAt,
      });
  const remoteWorkspaceHasExplicitCustomerReminder =
    hasOwnWorkspaceValue(remoteWorkspace, 'customerReminderHoursBefore') &&
    (typeof remoteWorkspace?.customerReminderHoursBefore === 'number' ||
      (typeof remoteWorkspace?.customerReminderHoursBefore === 'string' &&
        String(remoteWorkspace.customerReminderHoursBefore).trim() !== ''));
  const remoteWorkspaceHasExplicitInternalTester =
    hasOwnWorkspaceValue(remoteWorkspace, 'isInternalTester') &&
    typeof remoteWorkspace?.isInternalTester === 'boolean';
  return normalizeWorkspace(
    {
      ...local,
      id: remote.id || local.id,
      ownerEmail: normalizeAccountEmail(
        remote.ownerEmail || local.ownerEmail || normalizedEmail,
      ),
      salonCode: normalizeSalonCode(remote.salonCode || local.salonCode),
      salonName: pickNonEmptyWorkspaceValue(remote.salonName, local.salonName),
      salonNameDisplayStyle:
        confirmedBranding?.salonNameDisplayStyle ?? (local.salonNameDisplayStyle !== 'corsivo' &&
        remote.salonNameDisplayStyle === 'corsivo'
          ? local.salonNameDisplayStyle
          : remote.salonNameDisplayStyle),
      salonNameFontVariant:
        confirmedBranding?.salonNameFontVariant ?? (local.salonNameFontVariant !== 'neon' &&
        remote.salonNameFontVariant === 'neon'
          ? local.salonNameFontVariant
          : remote.salonNameFontVariant),
      salonBrandingUpdatedAt: confirmedBranding?.salonBrandingUpdatedAt,
      additionalPhones: hasOwnWorkspaceValue(remoteWorkspace, 'additionalPhones') ? remote.additionalPhones : local.additionalPhones,
      businessPhone: pickNonEmptyWorkspaceValue(
        remote.businessPhone,
        local.businessPhone,
      ),
      activityCategory: pickNonEmptyWorkspaceValue(
        remote.activityCategory,
        local.activityCategory,
      ),
      streetType: pickNonEmptyWorkspaceValue(
        remote.streetType,
        local.streetType,
      ),
      streetName: pickNonEmptyWorkspaceValue(
        remote.streetName,
        local.streetName,
      ),
      streetNumber: pickNonEmptyWorkspaceValue(
        remote.streetNumber,
        local.streetNumber,
      ),
      city: pickNonEmptyWorkspaceValue(remote.city, local.city),
      postalCode: pickNonEmptyWorkspaceValue(
        remote.postalCode,
        local.postalCode,
      ),
      salonAddress: pickNonEmptyWorkspaceValue(
        remote.salonAddress,
        local.salonAddress,
      ),
      subscriptionPlan: remote.subscriptionPlan ?? local.subscriptionPlan,
      subscriptionStatus: remote.subscriptionStatus ?? local.subscriptionStatus,
      isInternalTester: remoteWorkspaceHasExplicitInternalTester
        ? remote.isInternalTester
        : local.isInternalTester,
      createdAt: remote.createdAt || local.createdAt,
      updatedAt: remote.updatedAt || local.updatedAt,
      cashSectionDisabled:
        typeof remoteWorkspace?.cashSectionDisabled === 'boolean'
          ? remote.cashSectionDisabled
          : local.cashSectionDisabled,
      autoAcceptBookingRequests: preferLocalAutoAccept
        ? local.autoAcceptBookingRequests
        : remote.autoAcceptBookingRequests,
      autoAcceptBookingRequestsUpdatedAt:
        (preferLocalAutoAccept
          ? pickNonEmptyWorkspaceValue(
              local.autoAcceptBookingRequestsUpdatedAt,
              remote.autoAcceptBookingRequestsUpdatedAt,
            )
          : pickNonEmptyWorkspaceValue(
              remote.autoAcceptBookingRequestsUpdatedAt,
              local.autoAcceptBookingRequestsUpdatedAt,
            )) || undefined,
      customerReminderHoursBefore: remoteWorkspaceHasExplicitCustomerReminder
        ? remote.customerReminderHoursBefore
        : local.customerReminderHoursBefore,
      trialEndsAt:
        pickNonEmptyWorkspaceValue(remote.trialEndsAt, local.trialEndsAt) ||
        undefined,
      subscriptionEndsAt:
        pickNonEmptyWorkspaceValue(
          remote.subscriptionEndsAt,
          local.subscriptionEndsAt,
        ) || undefined,
      lastBackupAt:
        pickNonEmptyWorkspaceValue(remote.lastBackupAt, local.lastBackupAt) ||
        undefined,
    },
    normalizedEmail,
  );
};

const isUuidValue = (value?: string | null) =>
  !!value &&
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    value,
  );

const createOwnerCustomerId = () => {
  const nativeUuid = globalThis.crypto?.randomUUID?.();
  if (isUuidValue(nativeUuid)) {
    return nativeUuid.toLowerCase();
  }

  const bytes = new Uint8Array(16);
  if (typeof globalThis.crypto?.getRandomValues === 'function') {
    globalThis.crypto.getRandomValues(bytes);
  } else {
    for (let index = 0; index < bytes.length; index += 1) {
      bytes[index] = Math.floor(Math.random() * 256);
    }
    const timestamp = Date.now();
    for (let index = 0; index < 6; index += 1) {
      bytes[bytes.length - 1 - index] ^=
        Math.floor(timestamp / 256 ** index) & 0xff;
    }
  }

  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = Array.from(bytes, (value) =>
    value.toString(16).padStart(2, '0'),
  ).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(
    12,
    16,
  )}-${hex.slice(16, 20)}-${hex.slice(20)}`;
};

const normalizeTimeIdentity = (value?: string | null) => {
  const normalized = normalizeIdentityText(value);
  if (!normalized) return '';

  try {
    return String(timeToMinutes(normalized));
  } catch {
    return normalized;
  }
};
const buildAppointmentIdentityKey = ({
  date,
  time,
  customerName,
  serviceName,
  operatorId,
  operatorName,
}: {
  date: string;
  time: string;
  customerName: string;
  serviceName: string;
  operatorId?: string | null;
  operatorName?: string | null;
}) =>
  [
    date,
    normalizeTimeIdentity(time),
    normalizeIdentityText(customerName),
    normalizeIdentityText(serviceName),
    normalizeIdentityText(operatorId),
    normalizeIdentityText(operatorName),
  ].join('::');

const buildAppointmentIdentityKeyByCustomerSlot = ({
  date,
  time,
  customerName,
  serviceName,
  roleName,
  operatorId,
  operatorName,
}: {
  date: string;
  time: string;
  customerName: string;
  serviceName?: string | null;
  roleName?: string | null;
  operatorId?: string | null;
  operatorName?: string | null;
}) =>
  [
    date,
    normalizeTimeIdentity(time),
    normalizeIdentityText(customerName),
    normalizeIdentityText(serviceName),
    normalizeRoleName(roleName ?? ''),
    normalizeIdentityText(operatorId),
    normalizeIdentityText(operatorName),
  ].join('::');

const buildAppointmentMergeGuardKey = ({
  date,
  time,
  customerName,
  serviceName,
  operatorId,
  operatorName,
}: {
  date: string;
  time: string;
  customerName: string;
  serviceName: string;
  operatorId?: string | null;
  operatorName?: string | null;
}) =>
  `merge::${[
    (date ?? '').trim(),
    normalizeTimeIdentity(time),
    normalizeIdentityText(customerName),
    normalizeIdentityText(serviceName),
    normalizeIdentityText(operatorId),
    normalizeIdentityText(operatorName),
  ].join('|')}`;

const buildAppointmentIdGuardKey = (appointmentId?: string | null) => {
  const normalizedId = String(appointmentId ?? '').trim();
  return normalizedId ? `id::${normalizedId}` : '';
};

