const scheduleDelayedPushFlush = (delayMs = 1200) => {
  setTimeout(() => {
    void flushQueuedPushNotifications().catch((error) => {
      if (!shouldSilenceTransientSyncError(error)) {
        console.log('Flush push ritardato non riuscito:', error);
      }
    });
  }, delayMs);
};
const scheduleResilientPushFlushes = (
  delaysMs: number[] = [1200, 3500, 8000],
) => {
  delaysMs.forEach((delayMs) => {
    scheduleDelayedPushFlush(delayMs);
  });
};

const OWNER_PASSWORD_RESET_ROUTE = 'reset-password';
const resolvePublicClientBaseUrl = () => {
  const expoExtra =
    (Constants.expoConfig?.extra as
      { publicClientBaseUrl?: string } | undefined) ?? undefined;
  const manifestExtra =
    ((
      Constants as typeof Constants & {
        manifest?: { extra?: { publicClientBaseUrl?: string } };
      }
    ).manifest?.extra as { publicClientBaseUrl?: string } | undefined) ??
    undefined;
  const manifest2Extra =
    ((
      Constants as typeof Constants & {
        manifest2?: {
          extra?: { expoClient?: { extra?: { publicClientBaseUrl?: string } } };
        };
      }
    ).manifest2?.extra?.expoClient?.extra as
      { publicClientBaseUrl?: string } | undefined) ?? undefined;

  const configuredBaseUrl =
    expoExtra?.publicClientBaseUrl ??
    manifestExtra?.publicClientBaseUrl ??
    manifest2Extra?.publicClientBaseUrl ??
    DEFAULT_PUBLIC_CLIENT_BASE_URL;
  const normalizedValue = configuredBaseUrl?.trim().replace(/\/+$/, '');

  if (!normalizedValue) {
    return null;
  }

  try {
    const url = new URL(
      /^https?:\/\//i.test(normalizedValue)
        ? normalizedValue
        : `https://${normalizedValue}`,
    );
    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      return null;
    }

    url.hash = '';
    url.search = '';
    url.pathname = url.pathname.replace(/\/+$/, '');

    return url.toString().replace(/\/+$/, '');
  } catch {
    return null;
  }
};

const buildOwnerAuthRedirectUrl = (mode: 'signup' | 'recovery') => {
  if (mode === 'recovery') {
    const publicClientBaseUrl =
      resolvePublicClientBaseUrl() ?? DEFAULT_PUBLIC_CLIENT_BASE_URL;
    return `${publicClientBaseUrl}/${OWNER_PASSWORD_RESET_ROUTE}?recovery=1`;
  }

  return ExpoLinking.createURL('', {
    scheme: 'salonpro',
    queryParams: { confirmed: '1', side: 'owner' },
  });
};

const parseSupabaseAuthCallbackUrl = (incomingUrl?: string | null) => {
  const normalizedUrl = incomingUrl?.trim();
  if (!normalizedUrl) {
    return null;
  }

  try {
    const parsedUrl = new URL(normalizedUrl);
    const searchParams = parsedUrl.searchParams;
    const hashParams = new URLSearchParams(parsedUrl.hash.replace(/^#/, ''));

    const accessToken =
      hashParams.get('access_token') ??
      searchParams.get('access_token') ??
      undefined;
    const refreshToken =
      hashParams.get('refresh_token') ??
      searchParams.get('refresh_token') ??
      undefined;
    const code =
      searchParams.get('code') ?? hashParams.get('code') ?? undefined;
    const tokenHash =
      searchParams.get('token_hash') ??
      hashParams.get('token_hash') ??
      undefined;
    const eventType =
      hashParams.get('type') ?? searchParams.get('type') ?? undefined;
    const isRecovery =
      searchParams.get('recovery') === '1' ||
      hashParams.get('recovery') === '1' ||
      eventType === 'recovery';

    if ((!accessToken || !refreshToken) && !code && !tokenHash) {
      return null;
    }

    return {
      accessToken,
      refreshToken,
      code,
      tokenHash,
      eventType,
      isRecovery,
    };
  } catch (error) {
    console.log('Errore parsing callback auth Supabase:', error);
    return null;
  }
};

const buildCustomerIdentityKey = (item: {
  id?: string | null;
  nome?: string | null;
  telefono?: string | null;
  email?: string | null;
}) => {
  const normalizedPhone = normalizePhoneForIdentity(item.telefono);
  if (normalizedPhone) return `phone:${normalizedPhone}`;

  const normalizedEmail = normalizeIdentityText(item.email);
  if (normalizedEmail) return `email:${normalizedEmail}`;

  const normalizedName = normalizeIdentityText(item.nome);
  if (normalizedName) return `name:${normalizedName}`;

  return `id:${normalizeIdentityText(item.id)}`;
};

const buildCustomerIdentityAliases = (item: {
  id?: string | null;
  nome?: string | null;
  telefono?: string | null;
  email?: string | null;
}) =>
  Array.from(
    new Set(
      [
        buildCustomerIdentityKey(item),
        normalizePhoneForIdentity(item.telefono)
          ? `phone:${normalizePhoneForIdentity(item.telefono)}`
          : '',
        normalizeIdentityText(item.email)
          ? `email:${normalizeIdentityText(item.email)}`
          : '',
        normalizeIdentityText(item.nome)
          ? `name:${normalizeIdentityText(item.nome)}`
          : '',
        normalizeIdentityText(item.id)
          ? `id:${normalizeIdentityText(item.id)}`
          : '',
      ].filter(Boolean),
    ),
  );

// A deletion belongs to one persisted customer incarnation, not forever to
// their phone or email.  Contact aliases are still used for temporary/request
// projections, where no stable UUID exists, so stale derived rows cannot
// reappear while the canonical customer is being removed.
const isCustomerBlockedByDeletionGuard = (
  item: {
    id?: string | null;
    nome?: string | null;
    telefono?: string | null;
    email?: string | null;
  },
  deletedKeys: { has: (key: string) => boolean },
) => {
  const normalizedId = normalizeIdentityText(item.id);
  if (isUuidValue(normalizedId)) {
    return deletedKeys.has(`id:${normalizedId}`);
  }

  return buildCustomerIdentityAliases(item).some((alias) =>
    deletedKeys.has(alias),
  );
};

const customerRequestKeepsCustomerAlive = (
  item: Pick<RichiestaPrenotazione, 'stato'>,
) => item.stato === 'In attesa' || item.stato === 'Accettata';

const shouldDeriveFrontendCustomerFromRequest = (
  request: Pick<RichiestaPrenotazione, 'origine' | 'stato'>,
) =>
  (request.origine ?? 'frontend') === 'frontend' &&
  customerRequestKeepsCustomerAlive(request);

const isCustomerRequestFutureOrToday = (
  item: Pick<RichiestaPrenotazione, 'data' | 'ora'>,
) => {
  const normalizedDate = item.data?.trim() ?? '';
  if (!normalizedDate) {
    return false;
  }

  const todayDate = getTodayDateString();
  if (normalizedDate > todayDate) {
    return true;
  }

  if (normalizedDate < todayDate) {
    return false;
  }

  const normalizedTime = item.ora?.trim() ?? '';
  if (!normalizedTime) {
    return true;
  }

  try {
    const now = new Date();
    const currentMinutes = now.getHours() * 60 + now.getMinutes();
    return timeToMinutes(normalizedTime) >= currentMinutes;
  } catch {
    return true;
  }
};

const isHistoricalTerminalRequest = (
  item: Pick<RichiestaPrenotazione, 'data' | 'ora' | 'stato'>,
) => !isCustomerRequestFutureOrToday(item) && item.stato !== 'In attesa';

