  `${baseKey}__${normalizeAccountEmail(accountEmail)}`;
const AGENDA_DENSITY_SURFACE: AgendaDensitySurface =
  Platform.OS === 'web' ? 'web' : 'app';
const buildAgendaDensityPreferenceStorageKey = (
  accountEmail: string,
  workspaceId: string,
  surface: AgendaDensitySurface,
) =>
  `${buildScopedStorageKey(
    STORAGE_KEYS.workspace_agenda_density_preference,
    accountEmail,
  )}__${workspaceId.trim().toLowerCase()}__${surface}`;
const buildLegacyUnifiedAgendaDensityPreferenceStorageKey = (
  accountEmail: string,
  workspaceId: string,
) =>
  `${buildScopedStorageKey(
    'salon_manager_workspace_agenda_density_preference_v2',
    accountEmail,
  )}__${workspaceId.trim().toLowerCase()}`;
const LEGACY_AGENDA_DENSITY_STORAGE_KEY =
  `salonpro:agenda-density:v1:${Platform.OS}`;

type AgendaDensityPreferenceCacheRecord = {
  version: 3;
  workspaceId: string;
  surface: AgendaDensitySurface;
  densityId: AgendaDensityId;
  hasExplicitSelection: boolean;
  pendingRemoteSync: boolean;
  localUpdatedAt?: string;
  remoteUpdatedAt?: string;
};

type AgendaDensityAuthorityPayload = {
  workspaceId?: unknown;
  surface?: unknown;
  densityId?: unknown;
  updatedAt?: unknown;
  applied?: unknown;
};

type NormalizedAgendaDensityAuthority = {
  workspaceId: string;
  surface: AgendaDensitySurface;
  densityId: AgendaDensityId | null;
  updatedAt?: string;
  applied?: boolean;
};

const normalizeAgendaDensityTimestamp = (value: unknown) => {
  const normalized = String(value ?? '').trim();
  if (!normalized || !Number.isFinite(Date.parse(normalized))) {
    return undefined;
  }
  return new Date(normalized).toISOString();
};

const parseAgendaDensityPreferenceCache = (
  value: string | null | undefined,
  workspaceId: string,
  surface: AgendaDensitySurface,
): AgendaDensityPreferenceCacheRecord | null => {
  if (!value) return null;

  try {
    const parsed = JSON.parse(value) as {
      version?: unknown;
      workspaceId?: unknown;
      surface?: unknown;
      densityId?: unknown;
      hasExplicitSelection?: unknown;
      pendingRemoteSync?: unknown;
      localUpdatedAt?: unknown;
      remoteUpdatedAt?: unknown;
    };
    const densityId = normalizeAgendaDensityId(parsed.densityId);
    const normalizedWorkspaceId = String(parsed.workspaceId ?? '')
      .trim()
      .toLowerCase();
    if (
      (parsed.version !== 2 && parsed.version !== 3) ||
      normalizedWorkspaceId !== workspaceId.trim().toLowerCase() ||
      (parsed.version === 3 && parsed.surface !== surface) ||
      !densityId ||
      parsed.hasExplicitSelection !== true
    ) {
      return null;
    }

    return {
      version: 3,
      workspaceId: normalizedWorkspaceId,
      surface,
      densityId,
      hasExplicitSelection: true,
      pendingRemoteSync: parsed.pendingRemoteSync === true,
      localUpdatedAt: normalizeAgendaDensityTimestamp(parsed.localUpdatedAt),
      remoteUpdatedAt: normalizeAgendaDensityTimestamp(
        parsed.remoteUpdatedAt,
      ),
    };
  } catch {
    return null;
  }
};

const buildDefaultAgendaDensityPreference = (
  workspaceId = '',
  surface: AgendaDensitySurface = AGENDA_DENSITY_SURFACE,
): AgendaDensityPreference => ({
  workspaceId: workspaceId.trim().toLowerCase(),
  surface,
  densityId: getDefaultAgendaDensityId(surface),
  source: 'default',
  hasExplicitSelection: false,
  pendingRemoteSync: false,
});

const normalizeAgendaDensityAuthorityPayload = (
  value: unknown,
  expectedWorkspaceId: string,
  expectedSurface: AgendaDensitySurface,
): NormalizedAgendaDensityAuthority | null => {
  const unwrapped = Array.isArray(value) ? value[0] : value;
  if (!unwrapped || typeof unwrapped !== 'object') return null;

  const payload = unwrapped as AgendaDensityAuthorityPayload;
  const workspaceId = String(payload.workspaceId ?? '')
    .trim()
    .toLowerCase();
  if (workspaceId !== expectedWorkspaceId.trim().toLowerCase()) {
    return null;
  }
  const surface = String(payload.surface ?? '')
    .trim()
    .toLowerCase();
  if (surface !== expectedSurface) return null;

  const densityId = normalizeAgendaDensityId(payload.densityId);
  const updatedAt = normalizeAgendaDensityTimestamp(payload.updatedAt);
  if ((densityId && !updatedAt) || (!densityId && updatedAt)) {
    return null;
  }

  return {
    workspaceId,
    surface: expectedSurface,
    densityId,
    updatedAt,
    ...(typeof payload.applied === 'boolean'
      ? { applied: payload.applied }
      : {}),
  };
};

const buildAgendaDensityPreferenceResult = (
  preference: AgendaDensityPreference,
  ok: boolean,
  error?: string,
): AgendaDensityPreferenceResult => ({
  ok,
  surface: preference.surface,
  densityId: preference.densityId,
  source: preference.source,
  pendingRemoteSync: preference.pendingRemoteSync,
  updatedAt: preference.updatedAt,
  ...(error ? { error } : {}),
});
