const getOwnerAppointmentSaveErrorMessage = (error: unknown) => {
  const message = getOwnerBootstrapErrorMessage(error).toLowerCase();

  if (message.includes('owner_operator_overlap')) {
    return 'L’operatore ha già un impegno nello stesso intervallo.';
  }

  if (message.includes('owner_customer_overlap')) {
    return 'Il cliente ha già un impegno nello stesso intervallo.';
  }

  if (
    message.includes('target_slot_occupied') ||
    message.includes('target_start_slot_occupied') ||
    message.includes('slot_unavailable') ||
    message.includes('appointment_group_conflict')
  ) {
    return 'Questo incastro non è più disponibile: una fase di lavoro o la fase finale occupa già l’operatore. Aggiorna l’Agenda oppure scegli un altro spazio.';
  }

  if (message.includes('operator_service_not_enabled')) {
    return 'L’operatore scelto non è abilitato a eseguire questo servizio. Scegli un operatore compatibile.';
  }

  if (message.includes('operator_not_available')) {
    return 'L’operatore scelto non è disponibile in questo giorno o in questo orario.';
  }

  if (
    message.includes('invalid_phase_snapshot') ||
    message.includes('invalid_phase') ||
    message.includes('phase_snapshot')
  ) {
    return 'La configurazione delle fasi del servizio non è valida. Controlla lavoro, posa e fase finale.';
  }

  if (
    message.includes('outside_opening_hours') ||
    message.includes('outside_business_hours') ||
    message.includes('closing_time') ||
    message.includes('lunch_break')
  ) {
    return 'Il servizio non entra completamente nell’orario disponibile del salone.';
  }

  return 'Non sono riuscito a salvare l’appuntamento. Aggiorna l’Agenda e riprova.';
};

const getOwnerAppointmentSaveErrorCode = (error: unknown) => {
  const message = getOwnerBootstrapErrorMessage(error).toLowerCase();
  if (
    message.includes('owner_operator_overlap') ||
    message.includes('target_slot_occupied') ||
    message.includes('target_start_slot_occupied') ||
    message.includes('slot_unavailable') ||
    message.includes('appointment_group_conflict')
  ) {
    return 'operator_overlap' as const;
  }
  if (
    message.includes('owner_customer_overlap') ||
    message.includes('customer_time_overlap') ||
    message.includes('customer_time_conflict') ||
    message.includes('customer_terminal_pause_overlap') ||
    message.includes('terminal_pause_customer_overlap')
  ) {
    return 'customer_time_overlap' as const;
  }
  if (
    message.includes('create_owner_appointment_flexible_v1') ||
    message.includes('create_owner_appointment_group_flexible_v1')
  ) {
    return 'owner_contract_unavailable' as const;
  }
  return undefined;
};

const wait = (ms: number) =>
  new Promise<void>((resolve) => {
    setTimeout(resolve, ms);
  });

const awaitAndroidOwnerLogoutStep = async <T,>(
  operation: Promise<T>,
  timeoutMs: number,
  timeoutCode: string,
): Promise<T> => {
  if (Platform.OS !== 'android') {
    return operation;
  }

  let timeout: ReturnType<typeof setTimeout> | null = null;
  try {
    return await Promise.race([
      operation,
      new Promise<T>((_resolve, reject) => {
        timeout = setTimeout(() => reject(new Error(timeoutCode)), timeoutMs);
      }),
    ]);
  } finally {
    if (timeout) clearTimeout(timeout);
  }
};

const OWNER_AUTO_ACCEPT_AUTHORITY_TIMEOUT_MS = 8000;
const withOwnerAutoAcceptAuthorityTimeout = async <T,>(
  operation: Promise<T>,
): Promise<T> => {
  let timeout: ReturnType<typeof setTimeout> | null = null;
  try {
    return await Promise.race([
      operation,
      new Promise<T>((_resolve, reject) => {
        timeout = setTimeout(
          () => reject(new Error('owner_auto_accept_authority_timeout')),
          OWNER_AUTO_ACCEPT_AUTHORITY_TIMEOUT_MS,
        );
      }),
    ]);
  } finally {
    if (timeout) clearTimeout(timeout);
  }
};

const invokeBookingRequestStatusRpcWithSchemaRetry = async (
  rpcName:
    | 'accept_owner_booking_request_atomic_v2'
    | 'accept_owner_booking_request_with_duration_v1'
    | 'accept_owner_booking_request_with_operator_v1'
    | 'accept_owner_booking_request_with_operator_v2'
    | 'accept_owner_phased_booking_request_direct_v1'
    | 'update_owner_booking_request_status_v2'
    | 'finalize_owner_booking_request_accept_lightweight_v2',
  payload: Record<string, unknown>,
) => {
  const firstResponse = await supabase.rpc(rpcName, payload);

  if (
    !firstResponse.error ||
    (!isSupabaseSchemaCacheLookupError(firstResponse.error) &&
      !isStatementTimeoutError(firstResponse.error) &&
      !isCorruptedToastIndexError(firstResponse.error))
  ) {
    return firstResponse;
  }

  console.log(
    `Retry RPC ${rpcName} dopo errore transitorio Supabase:`,
    firstResponse.error,
  );
  await wait(450);

  const secondResponse = await supabase.rpc(rpcName, payload);
  if (
    !secondResponse.error ||
    (!isSupabaseSchemaCacheLookupError(secondResponse.error) &&
      !isStatementTimeoutError(secondResponse.error) &&
      !isCorruptedToastIndexError(secondResponse.error))
  ) {
    return secondResponse;
  }

  console.log(
    `Secondo retry RPC ${rpcName} dopo errore transitorio Supabase:`,
    secondResponse.error,
  );
  await wait(900);

  return supabase.rpc(rpcName, payload);
};

const invokeRpcWithSchemaRetry = async <TResponse = unknown,>(
  rpcName: string,
  payload: Record<string, unknown>,
) => {
  const invokeRpc = () =>
    Promise.resolve(supabase.rpc(rpcName, payload)) as Promise<{
      data: TResponse;
      error: PostgrestError | null;
    }>;

  const firstResponse = await invokeRpc();

  if (
    !firstResponse.error ||
    (!isSupabaseSchemaCacheLookupError(firstResponse.error) &&
      !isStatementTimeoutError(firstResponse.error) &&
      !isCorruptedToastIndexError(firstResponse.error))
  ) {
    return firstResponse;
  }

  await wait(450);
  const secondResponse = await invokeRpc();
  if (
    !secondResponse.error ||
    (!isSupabaseSchemaCacheLookupError(secondResponse.error) &&
      !isStatementTimeoutError(secondResponse.error) &&
      !isCorruptedToastIndexError(secondResponse.error))
  ) {
    return secondResponse;
  }

  await wait(900);
  return invokeRpc();
};

// Booking-create RPCs are mutating operations. Retrying the same phased write
// inside the generic schema/timeout helper and then again in the caller can
// multiply one slow request into many concurrent or serial mutations. Keep a
// single transport attempt here; compatibility fallbacks and the bounded,
// reconciliation-aware retry policy live at the booking call site.
const invokeBookingCreateRpcOnce = async <TResponse = unknown,>(
  rpcName: string,
  payload: Record<string, unknown>,
) =>
  Promise.resolve(supabase.rpc(rpcName, payload)) as Promise<{
    data: TResponse;
    error: PostgrestError | null;
  }>;

const isNamedRpcUnavailableError = (
  rpcName: string,
  error: unknown,
  expectedArgumentMarkers: string[] = [],
) => {
  if (isSupabaseSchemaCacheLookupError(error)) {
    return true;
  }

  const message = getOwnerBootstrapErrorMessage(error).toLowerCase();
  const normalizedRpcName = rpcName.toLowerCase();
  const referencesRpc =
    message.includes(`public.${normalizedRpcName}`) ||
    (message.includes('function') && message.includes(normalizedRpcName));

  if (!referencesRpc) {
    return false;
  }

  return (
    message.includes('could not find the function') ||
    (message.includes('function') && message.includes('does not exist')) ||
    expectedArgumentMarkers.some((marker) =>
      message.includes(marker.toLowerCase()),
    )
  );
};

type CancelOwnerAppointmentRpcPayload = {
  p_appointment_id: string | null;
  p_cancellation_event_id: string | null;
  p_appointment_date: string;
  p_appointment_time: string;
  p_customer_name: string;
  p_service_name: string;
  p_owner_email: string;
  p_salon_code: string;
  p_customer_email: string | null;
  p_customer_phone: string | null;
  p_required_role: string | null;
  p_operator_id: string | null;
  p_operator_name: string | null;
};

const isCancelOwnerAppointmentRpcSignatureMismatch = (error: unknown) => {
  const message = getOwnerBootstrapErrorMessage(error).toLowerCase();

  return (
    (message.includes('public.cancel_owner_linked_appointment_v1') ||
      message.includes('public.cancel_owner_appointment_lane_guarded') ||
      message.includes('public.cancel_owner_appointment')) &&
    (message.includes('could not find the function') ||
      (message.includes('function') && message.includes('does not exist')) ||
      message.includes('schema cache') ||
      message.includes('p_required_role') ||
      message.includes('p_operator_id') ||
      message.includes('p_operator_name'))
  );
};

const invokeCancelOwnerAppointmentRpcCompat = async (
  payload: CancelOwnerAppointmentRpcPayload,
) => {
  if (payload.p_appointment_id) {
    const linkedResponse = await invokeRpcWithSchemaRetry(
      'cancel_owner_linked_appointment_v1',
      payload,
    );
    if (
      !linkedResponse.error ||
      !isCancelOwnerAppointmentRpcSignatureMismatch(linkedResponse.error)
    ) {
      return linkedResponse;
    }
  }

  const preferredResponse = await invokeRpcWithSchemaRetry(
    'cancel_owner_appointment_lane_guarded',
    payload,
  );
  if (
    !preferredResponse.error ||
    !isCancelOwnerAppointmentRpcSignatureMismatch(preferredResponse.error)
  ) {
    return preferredResponse;
  }

  const {
    p_required_role: _ignoredRequiredRole,
    p_operator_id: _ignoredOperatorId,
    p_operator_name: _ignoredOperatorName,
    ...legacyPayload
  } = payload;

  return invokeRpcWithSchemaRetry('cancel_owner_appointment', legacyPayload);
};

const isPublicBookingRequestRpcSignatureMismatch = (error: unknown) => {
  const message = getOwnerBootstrapErrorMessage(error).toLowerCase();

  return (
    message.includes('public.create_public_booking_request') &&
    (message.includes('could not find the function') ||
      (message.includes('function') && message.includes('does not exist')) ||
      message.includes('schema cache') ||
      message.includes('p_required_role') ||
      message.includes('p_operator_id') ||
      message.includes('p_operator_name'))
  );
};

const invokeCreatePublicBookingRequestRpcCompat = async (payload: {
  p_salon_code: string;
  p_requested_service_name: string;
  p_requested_price: number;
  p_requested_duration_minutes: number;
  p_appointment_date: string;
  p_appointment_time: string;
  p_customer_name: string;
  p_customer_surname: string;
  p_customer_email: string;
  p_customer_phone: string;
  p_customer_instagram: string | null;
  p_notes: string | null;
  p_required_role: string | null;
  p_operator_id: string | null;
  p_operator_name: string | null;
  p_phase_snapshot?: ServicePhaseConfig | null;
}) => {
  const normalizedPhaseSnapshot = normalizeServicePhaseConfig(
    payload.p_phase_snapshot,
  );
  if (normalizedPhaseSnapshot) {
    const phasedPayload = {
      ...payload,
      p_phase_snapshot: normalizedPhaseSnapshot,
    };
    const customerTimingResponse = await invokeBookingCreateRpcOnce(
      'create_public_phased_booking_request_v5',
      phasedPayload,
    );
    if (
      !customerTimingResponse.error ||
      !isNamedRpcUnavailableError(
        'create_public_phased_booking_request_v5',
        customerTimingResponse.error,
      )
    ) {
      return customerTimingResponse;
    }
    const preferredResponse = await invokeBookingCreateRpcOnce(
      'create_public_phased_booking_request_v4',
      phasedPayload,
    );
    if (
      !preferredResponse.error ||
      !isNamedRpcUnavailableError(
        'create_public_phased_booking_request_v4',
        preferredResponse.error,
      )
    ) {
      return preferredResponse;
    }
    const v3Response = await invokeBookingCreateRpcOnce(
      'create_public_phased_booking_request_v3',
      phasedPayload,
    );
    if (
      !v3Response.error ||
      !isNamedRpcUnavailableError(
        'create_public_phased_booking_request_v3',
        v3Response.error,
      )
    ) {
      return v3Response;
    }
    const v2Response = await invokeBookingCreateRpcOnce(
      'create_public_phased_booking_request_v2',
      phasedPayload,
    );
    if (
      !v2Response.error ||
      !isNamedRpcUnavailableError(
        'create_public_phased_booking_request_v2',
        v2Response.error,
      )
    ) {
      return v2Response;
    }
    return invokeBookingCreateRpcOnce(
      'create_public_phased_booking_request_v1',
      phasedPayload,
    );
  }

  const { p_phase_snapshot: _ignoredPhaseSnapshot, ...standardPayload } =
    payload;
  const preferredRpcNames = [
    'create_public_booking_request_ultralight_v4',
    'create_public_booking_request_ultralight_v3',
    'create_public_booking_request_ultralight_v2',
    'create_public_booking_request_ultralight_v1',
    'create_public_booking_request_lightweight_v1',
  ] as const;

  for (const rpcName of preferredRpcNames) {
    const preferredResponse = await invokeRpcWithSchemaRetry(
      rpcName,
      standardPayload,
    );
    if (!preferredResponse.error) {
      return preferredResponse;
    }

    if (!isNamedRpcUnavailableError(rpcName, preferredResponse.error)) {
      return preferredResponse;
    }
  }

  const attemptPrimary = async () =>
    supabase.rpc('create_public_booking_request', standardPayload);

  const firstResponse = await attemptPrimary();
  if (!firstResponse.error) {
    return firstResponse;
  }

  if (isSupabaseSchemaCacheLookupError(firstResponse.error)) {
    await wait(450);
    const secondResponse = await attemptPrimary();
    if (!secondResponse.error) {
      return secondResponse;
    }

    if (isSupabaseSchemaCacheLookupError(secondResponse.error)) {
      await wait(900);
      const thirdResponse = await attemptPrimary();
      if (!thirdResponse.error) {
        return thirdResponse;
      }

      if (!isPublicBookingRequestRpcSignatureMismatch(thirdResponse.error)) {
        return thirdResponse;
      }
    } else if (
      !isPublicBookingRequestRpcSignatureMismatch(secondResponse.error)
    ) {
      return secondResponse;
    }
  } else if (!isPublicBookingRequestRpcSignatureMismatch(firstResponse.error)) {
    return firstResponse;
  }

  const legacyWithoutRequiredRole = await supabase.rpc(
    'create_public_booking_request',
    {
      p_salon_code: payload.p_salon_code,
      p_requested_service_name: payload.p_requested_service_name,
      p_requested_price: payload.p_requested_price,
      p_requested_duration_minutes: payload.p_requested_duration_minutes,
      p_appointment_date: payload.p_appointment_date,
      p_appointment_time: payload.p_appointment_time,
      p_customer_name: payload.p_customer_name,
      p_customer_surname: payload.p_customer_surname,
      p_customer_email: payload.p_customer_email,
      p_customer_phone: payload.p_customer_phone,
      p_customer_instagram: payload.p_customer_instagram,
      p_notes: payload.p_notes,
      p_operator_id: payload.p_operator_id,
      p_operator_name: payload.p_operator_name,
    },
  );

  if (
    !legacyWithoutRequiredRole.error ||
    !isPublicBookingRequestRpcSignatureMismatch(legacyWithoutRequiredRole.error)
  ) {
    return legacyWithoutRequiredRole;
  }

  return supabase.rpc('create_public_booking_request', {
    p_salon_code: payload.p_salon_code,
    p_requested_service_name: payload.p_requested_service_name,
    p_requested_price: payload.p_requested_price,
    p_requested_duration_minutes: payload.p_requested_duration_minutes,
    p_appointment_date: payload.p_appointment_date,
    p_appointment_time: payload.p_appointment_time,
    p_customer_name: payload.p_customer_name,
    p_customer_surname: payload.p_customer_surname,
    p_customer_email: payload.p_customer_email,
    p_customer_phone: payload.p_customer_phone,
    p_customer_instagram: payload.p_customer_instagram,
    p_notes: payload.p_notes,
  });
};

