const invokeCreateOwnerAppointmentRpcCompat = async (
  payload: OwnerAppointmentRpcPayload,
) => {
  if (payload.p_package_selection) {
    const { p_package_selection: selection, ...bookingPayload } = payload;
    return invokeRpcWithSchemaRetry('create_owner_package_appointment_v1', { p_package_id: selection.packageId, p_customer_id: selection.customerId, p_key: selection.operationId, p_payload: bookingPayload, p_group: false });
  }
  if (payload.p_occasional_customer) {
    return invokeRpcWithSchemaRetry('create_owner_occasional_appointment_v1', { p_payload: payload, p_group: false });
  }
  const flexibleResponse = await invokeRpcWithSchemaRetry(
    'create_owner_appointment_flexible_v1',
    payload,
  );
  if (
    !flexibleResponse.error ||
    !isNamedRpcUnavailableError(
      'create_owner_appointment_flexible_v1',
      flexibleResponse.error,
    )
  ) {
    return flexibleResponse;
  }

  const {
    p_allow_operator_overlap,
    p_allow_customer_overlap,
    p_allow_machinery_overlap,
    p_allow_outside_schedule: _ignoredAllowOutsideSchedule,
    p_allow_capability_override: _ignoredAllowCapabilityOverride,
    ...legacyCompatiblePayload
  } = payload;

  // Never pretend that a confirmed overlap was persisted when the dedicated
  // owner contract is not available yet. The old RPCs are intentionally kept
  // only as a non-forced compatibility path.
  if (
    p_allow_operator_overlap ||
    p_allow_customer_overlap ||
    p_allow_machinery_overlap
  ) {
    return flexibleResponse;
  }

  const normalizedPhaseSnapshot = normalizeServicePhaseConfig(
    legacyCompatiblePayload.p_phase_snapshot,
  );
  if (normalizedPhaseSnapshot) {
    const phasedPayload = {
      ...legacyCompatiblePayload,
      p_phase_snapshot: normalizedPhaseSnapshot,
    };
    const hardCapabilityResponse = await invokeRpcWithSchemaRetry(
      'create_owner_phased_appointment_v2',
      phasedPayload,
    );
    if (
      !hardCapabilityResponse.error ||
      !isNamedRpcUnavailableError(
        'create_owner_phased_appointment_v2',
        hardCapabilityResponse.error,
      )
    ) {
      return hardCapabilityResponse;
    }
    return invokeRpcWithSchemaRetry(
      'create_owner_phased_appointment_v1',
      phasedPayload,
    );
  }

  const { p_phase_snapshot: _ignoredPhaseSnapshot, ...standardPayload } =
    legacyCompatiblePayload;
  const preferredRpcNames = [
    'create_owner_appointment_ultralight_v3',
    'create_owner_appointment_ultralight_v2',
    'create_owner_appointment_ultralight_v1',
    'create_owner_appointment_lightweight_v1',
  ] as const;

  for (const rpcName of preferredRpcNames) {
    const preferredResponse = await invokeRpcWithSchemaRetry(
      rpcName,
      standardPayload,
    );
    if (!preferredResponse.error) {
      return preferredResponse;
    }

    if (
      getOwnerBootstrapErrorMessage(preferredResponse.error)
        .toLowerCase()
        .includes('p_required_role')
    ) {
      const { p_required_role: _ignoredRequiredRole, ...legacyPayload } =
        standardPayload;
      const retryWithoutRequiredRole = await invokeRpcWithSchemaRetry(
        rpcName,
        legacyPayload,
      );
      if (!retryWithoutRequiredRole.error) {
        return retryWithoutRequiredRole;
      }

      if (
        !isNamedRpcUnavailableError(rpcName, retryWithoutRequiredRole.error)
      ) {
        return retryWithoutRequiredRole;
      }
    }

    if (!isNamedRpcUnavailableError(rpcName, preferredResponse.error)) {
      return preferredResponse;
    }
  }

  const fallbackResponse = await invokeRpcWithSchemaRetry(
    'create_owner_appointment',
    standardPayload,
  );
  if (
    fallbackResponse.error &&
    getOwnerBootstrapErrorMessage(fallbackResponse.error)
      .toLowerCase()
      .includes('p_required_role')
  ) {
    const { p_required_role: _ignoredRequiredRole, ...legacyPayload } =
      standardPayload;
    return invokeRpcWithSchemaRetry('create_owner_appointment', legacyPayload);
  }

  return fallbackResponse;
};

const invokeFindPublicBookingRequestByCompositeRpcCompat = async (
  payload: PublicBookingRequestLookupRpcPayload,
) => {
  const primaryRpcName = 'find_public_booking_request_by_composite';
  const firstResponse = await invokeRpcWithSchemaRetry(primaryRpcName, payload);
  if (!firstResponse.error) {
    return firstResponse;
  }

  if (!isNamedRpcUnavailableError(primaryRpcName, firstResponse.error)) {
    return firstResponse;
  }

  return { data: null, error: null };
};

const buildOwnerBootstrapSlugCandidates = (
  salonName: string,
  email: string,
) => {
  const normalizedEmail = normalizeAccountEmail(email);
  const emailBase = normalizedEmail.split('@')[0] || 'salone';
  const compactEmailBase =
    emailBase.replace(/[^a-z0-9]/gi, '').toLowerCase() || 'owner';
  const nameBase =
    normalizeSalonCode(salonName) || normalizeSalonCode(emailBase) || 'salone';
  const defaultCode = buildSalonCode(salonName, normalizedEmail);

  return Array.from(
    new Set(
      [
        defaultCode,
        normalizeSalonCode(`${nameBase}-${compactEmailBase.slice(0, 10)}`),
        normalizeSalonCode(`${nameBase}-${compactEmailBase.slice(-10)}`),
        normalizeSalonCode(`${nameBase}-${compactEmailBase}`),
      ].filter(Boolean),
    ),
  );
};

