const selectCanonicalRemoteWorkspace = ({
  workspaces,
  preferredId,
  preferredSalonCode,
}: {
  workspaces: RemoteWorkspaceRow[];
  preferredId?: string | null;
  preferredSalonCode?: string | null;
}) => {
  const normalizedPreferredId = String(preferredId ?? '').trim();
  const normalizedPreferredSalonCode = normalizeSalonCode(
    preferredSalonCode ?? '',
  );

  return (
    (normalizedPreferredSalonCode
      ? workspaces.find(
          (item) =>
            normalizeSalonCode(String(item.slug ?? '')) ===
            normalizedPreferredSalonCode,
        )
      : null) ??
    (normalizedPreferredId
      ? workspaces.find(
          (item) => String(item.id ?? '').trim() === normalizedPreferredId,
        )
      : null) ??
    workspaces[0] ??
    null
  );
};

