const normalizeAvailabilitySettingsRpcPayload = (payload: unknown) => {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    return null;
  }

  const record = payload as Record<string, unknown>;
  const rawSettings =
    record.availabilitySettings ?? record.availability_settings ?? record;
  if (
    !rawSettings ||
    typeof rawSettings !== 'object' ||
    Array.isArray(rawSettings)
  ) {
    return null;
  }

  return normalizeAvailabilitySettings(rawSettings as AvailabilitySettings);
};

const pickGuidedSlotsAuthority = ({
  localSettings,
  snapshotSettings,
  remoteSettings,
}: {
  localSettings?: AvailabilitySettings | null;
  snapshotSettings?: AvailabilitySettings | null;
  remoteSettings?: AvailabilitySettings | null;
}) => {
  const candidates = [
    {
      source: 'local',
      settings: normalizeAvailabilitySettings(localSettings ?? null),
    },
    {
      source: 'snapshot',
      settings: normalizeAvailabilitySettings(snapshotSettings ?? null),
    },
    {
      source: 'remote',
      settings: normalizeAvailabilitySettings(remoteSettings ?? null),
    },
  ].filter((candidate) => hasExplicitGuidedSlotsSettings(candidate.settings));

  if (candidates.length === 0) {
    return null;
  }

  const bestTimestampCandidate = candidates
    .map((candidate) => ({
      ...candidate,
      updatedAtMs: getGuidedSlotsUpdatedAtMs(candidate.settings),
    }))
    .sort((left, right) => right.updatedAtMs - left.updatedAtMs)[0];

  if (
    bestTimestampCandidate &&
    Number.isFinite(bestTimestampCandidate.updatedAtMs) &&
    bestTimestampCandidate.updatedAtMs !== Number.NEGATIVE_INFINITY
  ) {
    return bestTimestampCandidate.settings;
  }

  const remoteCandidate = candidates.find(
    (candidate) => candidate.source === 'remote',
  );
  if (remoteCandidate) {
    return remoteCandidate.settings;
  }

  const snapshotCandidate = candidates.find(
    (candidate) => candidate.source === 'snapshot',
  );
  if (snapshotCandidate) {
    return snapshotCandidate.settings;
  }

  return (
    candidates.find((candidate) => candidate.source === 'local')?.settings ??
    null
  );
};

const resolveProtectedAvailabilitySettings = ({
  localSettings,
  snapshotSettings,
  remoteSettings,
  remoteIsAuthoritative = false,
}: {
  localSettings?: AvailabilitySettings | null;
  snapshotSettings?: AvailabilitySettings | null;
  remoteSettings?: AvailabilitySettings | null;
  remoteIsAuthoritative?: boolean;
}) => {
  const normalizedLocal = normalizeAvailabilitySettings(
    localSettings ?? normalizeAvailabilitySettings(),
  );
  const normalizedSnapshot = normalizeAvailabilitySettings(
    snapshotSettings ?? normalizeAvailabilitySettings(),
  );
  const normalizedRemote = normalizeAvailabilitySettings(
    remoteSettings ?? normalizeAvailabilitySettings(),
  );

  // La risposta remota resta la base autorevole per i campi ordinari. I gruppi
  // versionati continuano pero' a scegliere il timestamp piu recente: una
  // fetch partita prima di un salvataggio non puo' terminare dopo e far
  // rimbalzare la finestra prenotazioni al valore precedente.
  const baseSettings =
    remoteIsAuthoritative && remoteSettings
      ? normalizedRemote
      : hasMeaningfulAvailabilitySettings(normalizedLocal)
        ? normalizedLocal
        : hasMeaningfulAvailabilitySettings(normalizedSnapshot)
          ? normalizedSnapshot
          : hasMeaningfulAvailabilitySettings(normalizedRemote)
            ? normalizedRemote
            : normalizedLocal;

  const guidedAuthority = pickGuidedSlotsAuthority({
    localSettings: normalizedLocal,
    snapshotSettings: normalizedSnapshot,
    remoteSettings: normalizedRemote,
  });

  const withGuidedAuthority = guidedAuthority
    ? {
        ...baseSettings,
        guidedSlotsEnabled: guidedAuthority.guidedSlotsEnabled,
        guidedSlotsStrategy: guidedAuthority.guidedSlotsStrategy,
        guidedSlotsVisibility: guidedAuthority.guidedSlotsVisibility,
        guidedSlotsUpdatedAt: guidedAuthority.guidedSlotsUpdatedAt,
      }
    : baseSettings;

  const weekVisibleCandidates = [
    normalizedLocal,
    normalizedSnapshot,
    normalizedRemote,
  ].sort(
    (left, right) =>
      getWeekVisibleDaysUpdatedAtMs(right) -
      getWeekVisibleDaysUpdatedAtMs(left),
  );
  const weekVisibleAuthority = weekVisibleCandidates.find(
    (candidate) =>
      getWeekVisibleDaysUpdatedAtMs(candidate) !== Number.NEGATIVE_INFINITY,
  );

  const withWeekVisibleAuthority = weekVisibleAuthority
    ? {
        ...withGuidedAuthority,
        weekVisibleDays: weekVisibleAuthority.weekVisibleDays,
        weekVisibleDaysUpdatedAt: weekVisibleAuthority.weekVisibleDaysUpdatedAt,
      }
    : withGuidedAuthority;

  const publicBookingWindowCandidates = [
    normalizedLocal,
    normalizedSnapshot,
    normalizedRemote,
  ].sort(
    (left, right) =>
      getPublicBookingWindowUpdatedAtMs(right) -
      getPublicBookingWindowUpdatedAtMs(left),
  );
  const publicBookingWindowAuthority = publicBookingWindowCandidates.find(
    (candidate) =>
      getPublicBookingWindowUpdatedAtMs(candidate) !== Number.NEGATIVE_INFINITY,
  );
  const withPublicBookingWindowAuthority = publicBookingWindowAuthority
    ? {
        ...withWeekVisibleAuthority,
        publicBookingWindowValue:
          publicBookingWindowAuthority.publicBookingWindowValue,
        publicBookingWindowUnit:
          publicBookingWindowAuthority.publicBookingWindowUnit,
        publicBookingWindowUpdatedAt:
          publicBookingWindowAuthority.publicBookingWindowUpdatedAt,
      }
    : withWeekVisibleAuthority;

  const publicSlotIntervalAuthority = [
    normalizedLocal,
    normalizedSnapshot,
    normalizedRemote,
  ]
    .sort(
      (left, right) =>
        getPublicSlotIntervalUpdatedAtMs(right) -
        getPublicSlotIntervalUpdatedAtMs(left),
    )
    .find(
      (candidate) =>
        getPublicSlotIntervalUpdatedAtMs(candidate) !==
        Number.NEGATIVE_INFINITY,
    );
  const withPublicSlotIntervalAuthority = publicSlotIntervalAuthority
    ? {
        ...withPublicBookingWindowAuthority,
        publicSlotIntervalMode:
          publicSlotIntervalAuthority.publicSlotIntervalMode,
        publicSlotMinimumIntervalMinutes:
          publicSlotIntervalAuthority.publicSlotMinimumIntervalMinutes,
        publicSlotIntervalUpdatedAt:
          publicSlotIntervalAuthority.publicSlotIntervalUpdatedAt,
      }
    : withPublicBookingWindowAuthority;

  const weeklyScheduleCandidates = [
    normalizedLocal,
    normalizedSnapshot,
    normalizedRemote,
  ].sort(
    (left, right) =>
      getWeeklyScheduleUpdatedAtMs(right) - getWeeklyScheduleUpdatedAtMs(left),
  );
  const weeklyScheduleAuthority = weeklyScheduleCandidates.find(
    (candidate) =>
      getWeeklyScheduleUpdatedAtMs(candidate) !== Number.NEGATIVE_INFINITY,
  );
  const withWeeklyScheduleAuthority = weeklyScheduleAuthority
    ? {
        ...withPublicSlotIntervalAuthority,
        weeklySchedule: weeklyScheduleAuthority.weeklySchedule,
        weeklyScheduleUpdatedAt:
          weeklyScheduleAuthority.weeklyScheduleUpdatedAt,
        dateOverrides: weeklyScheduleAuthority.dateOverrides,
        vacationRanges: weeklyScheduleAuthority.vacationRanges,
        lunchBreakEnabled: weeklyScheduleAuthority.lunchBreakEnabled,
        lunchBreakStart: weeklyScheduleAuthority.lunchBreakStart,
        lunchBreakEnd: weeklyScheduleAuthority.lunchBreakEnd,
      }
    : withPublicSlotIntervalAuthority;

  const calendarExceptionsCandidates = [
    normalizedLocal,
    normalizedSnapshot,
    normalizedRemote,
  ].sort(
    (left, right) =>
      getCalendarExceptionsUpdatedAtMs(right) -
      getCalendarExceptionsUpdatedAtMs(left),
  );
  const calendarExceptionsAuthority = calendarExceptionsCandidates.find(
    (candidate) =>
      getCalendarExceptionsUpdatedAtMs(candidate) !== Number.NEGATIVE_INFINITY,
  );
  const withCalendarExceptionsAuthority = calendarExceptionsAuthority
    ? {
        ...withWeeklyScheduleAuthority,
        calendarExceptions: calendarExceptionsAuthority.calendarExceptions,
        calendarExceptionsUpdatedAt:
          calendarExceptionsAuthority.calendarExceptionsUpdatedAt,
      }
    : withWeeklyScheduleAuthority;

  const slotIntervalCandidates = [
    normalizedLocal,
    normalizedSnapshot,
    normalizedRemote,
  ].sort(
    (left, right) =>
      getSlotIntervalUpdatedAtMs(right) - getSlotIntervalUpdatedAtMs(left),
  );
  const slotIntervalAuthority = slotIntervalCandidates.find(
    (candidate) =>
      getSlotIntervalUpdatedAtMs(candidate) !== Number.NEGATIVE_INFINITY,
  );

  const withSlotIntervalAuthority = slotIntervalAuthority
    ? {
        ...withCalendarExceptionsAuthority,
        slotIntervalMinutes: slotIntervalAuthority.slotIntervalMinutes,
        scheduledSlotIntervalMinutes:
          slotIntervalAuthority.scheduledSlotIntervalMinutes,
        scheduledSlotIntervalEffectiveFrom:
          slotIntervalAuthority.scheduledSlotIntervalEffectiveFrom,
        slotIntervalUpdatedAt: slotIntervalAuthority.slotIntervalUpdatedAt,
        dateSlotIntervals: slotIntervalAuthority.dateSlotIntervals,
        agendaTimeMarkerIntervalMinutes:
          slotIntervalAuthority.agendaTimeMarkerIntervalMinutes,
      }
    : withCalendarExceptionsAuthority;

  const customServiceContactAuthority = [
    normalizedLocal,
    normalizedSnapshot,
    normalizedRemote,
  ]
    .sort(
      (left, right) =>
        getCustomServiceContactUpdatedAtMs(right) -
        getCustomServiceContactUpdatedAtMs(left),
    )
    .find(
      (candidate) =>
        getCustomServiceContactUpdatedAtMs(candidate) !==
        Number.NEGATIVE_INFINITY,
    );

  const withCustomServiceContactAuthority = customServiceContactAuthority
    ? {
        ...withSlotIntervalAuthority,
        customServiceContactEnabled:
          customServiceContactAuthority.customServiceContactEnabled,
        customServiceContactTitle:
          customServiceContactAuthority.customServiceContactTitle,
        customServiceContactMessage:
          customServiceContactAuthority.customServiceContactMessage,
        customServiceContactWhatsappMessage:
          customServiceContactAuthority.customServiceContactWhatsappMessage,
        customServiceContactUpdatedAt:
          customServiceContactAuthority.customServiceContactUpdatedAt,
      }
    : withSlotIntervalAuthority;

  const registrationAuthority = remoteIsAuthoritative && remoteSettings
    ? normalizedRemote
    : [normalizedRemote, normalizedSnapshot, normalizedLocal]
      .map((settings) => ({ settings, updatedAt: Date.parse(settings.customerRegistrationApprovalUpdatedAt ?? '') }))
      .filter((candidate) => Number.isFinite(candidate.updatedAt))
      .sort((left, right) => right.updatedAt - left.updatedAt)[0]?.settings;
  return registrationAuthority
    ? {
        ...withCustomServiceContactAuthority,
        customerRegistrationApprovalRequired: registrationAuthority.customerRegistrationApprovalRequired === true,
        customerRegistrationApprovalUpdatedAt: registrationAuthority.customerRegistrationApprovalUpdatedAt,
      }
    : withCustomServiceContactAuthority;
};

const normalizeServiceColorOverrideMap = (
  overrides: Record<string, string>,
  services: Servizio[],
) => {
  if (services.length === 0) {
    const next: Record<string, string> = {};

    Object.entries(overrides).forEach(([key, value]) => {
      const normalizedKey = key.trim();
      const normalizedValue = value.trim();
      if (!normalizedKey || !normalizedValue) return;
      next[normalizedKey] = normalizedValue;
    });

    return next;
  }

  const validServiceIds = new Set(
    services.map((service) => service.id?.trim() ?? '').filter(Boolean),
  );
  const validServiceNames = new Set(
    services
      .map((service) => normalizeServiceAccentKey(service.nome))
      .filter(Boolean),
  );
  const next: Record<string, string> = {};
  const colorsByServiceId: Record<string, string> = {};

  Object.entries(overrides).forEach(([key, value]) => {
    const normalizedKey = key.trim();
    const normalizedValue = normalizeServiceAccentColor(value);
    if (!normalizedKey || !normalizedValue) return;

    if (validServiceIds.has(normalizedKey)) {
      colorsByServiceId[normalizedKey] = normalizedValue;
      return;
    }

    const normalizedServiceKey = normalizeServiceAccentKey(normalizedKey);
    if (!normalizedServiceKey) {
      return;
    }

    // Le chiavi per nome restano come metadato cromatico degli appuntamenti
    // orfani. Un servizio eliminato non deve far cambiare colore allo storico.
    // Gli id legacy senza piu un servizio corrispondente, invece, non sono
    // risolvibili e possono essere scartati in sicurezza.
    if (!validServiceNames.has(normalizedServiceKey) && isUuidValue(normalizedKey)) {
      return;
    }

    next[normalizedServiceKey] = normalizedValue;
  });

  services.forEach((service) => {
    const stableKey = normalizeServiceAccentKey(service.nome);
    if (!stableKey) return;

    const existingColor =
      next[stableKey] || colorsByServiceId[service.id?.trim() ?? ''];

    if (existingColor) {
      next[stableKey] = existingColor;
    }
  });

  return next;
};

const normalizeRoleColorOverrideMap = (overrides: Record<string, string>) => {
  const next: Record<string, string> = {};

  Object.entries(overrides).forEach(([key, value]) => {
    const normalizedKey = normalizeRoleName(key);
    const normalizedValue = normalizeServiceAccentColor(value);
    if (!normalizedKey || !normalizedValue) return;
    next[normalizedKey] = normalizedValue;
  });

  return next;
};

const recoverLegacyRoleColorOverridesFromServiceMap = ({
  serviceOverrides,
  services,
}: {
  serviceOverrides?: Record<string, string>;
  services: Servizio[];
}) => {
  const next: Record<string, string> = {};
  const validRoles = new Set(
    services
      .map((service) => normalizeRoleName(service.mestiereRichiesto ?? ''))
      .filter(Boolean),
  );

  if (validRoles.size === 0) {
    return next;
  }

  Object.entries(serviceOverrides ?? {}).forEach(([key, value]) => {
    const normalizedRoleKey = normalizeRoleName(key);
    const normalizedValue = value.trim();
    if (!normalizedRoleKey || !normalizedValue) return;
    if (!validRoles.has(normalizedRoleKey)) return;
    next[normalizedRoleKey] = normalizedValue;
  });

  return next;
};

const mergeServiceColorOverrideMaps = ({
  remoteOverrides,
  localOverrides,
  services,
}: {
  remoteOverrides?: Record<string, string>;
  localOverrides?: Record<string, string>;
  services: Servizio[];
}) =>
  normalizeServiceColorOverrideMap(
    {
      ...(remoteOverrides ?? {}),
      ...(localOverrides ?? {}),
    },
    services,
  );

const mergeRoleColorOverrideMaps = ({
  remoteOverrides,
  localOverrides,
  remoteServiceOverrides,
  localServiceOverrides,
  services,
}: {
  remoteOverrides?: Record<string, string>;
  localOverrides?: Record<string, string>;
  remoteServiceOverrides?: Record<string, string>;
  localServiceOverrides?: Record<string, string>;
  services?: Servizio[];
}) =>
  normalizeRoleColorOverrideMap({
    ...(services?.length
      ? recoverLegacyRoleColorOverridesFromServiceMap({
          serviceOverrides: remoteServiceOverrides,
          services,
        })
      : {}),
    ...(remoteOverrides ?? {}),
    ...(services?.length
      ? recoverLegacyRoleColorOverridesFromServiceMap({
          serviceOverrides: localServiceOverrides,
          services,
        })
      : {}),
    ...(localOverrides ?? {}),
  });

type Operatore = {
  id: string;
  nome: string;
  mestiere: string;
  fotoUri?: string;
  availability?: OperatorAvailability;
  publicServiceMode?: 'all_role' | 'selected';
  publicServiceIds?: string[];
  publicServiceKeys?: string[];
};

type PendingOperatorPublicServiceAssignment = {
  operatorId: string;
  operatorNameKey: string;
  mode: 'all_role' | 'selected';
  serviceIds: string[];
  serviceKeys: string[];
  signature: string;
  timestamp: number;
};

const buildOperatorPublicServiceAssignmentSignature = (item: {
  publicServiceMode?: 'all_role' | 'selected';
  publicServiceIds?: string[];
  publicServiceKeys?: string[];
}) =>
  JSON.stringify({
    mode: item.publicServiceMode === 'selected' ? 'selected' : 'all_role',
    serviceIds: normalizeStringIdArray(item.publicServiceIds).sort(),
    serviceKeys: normalizeStringIdArray(item.publicServiceKeys).sort(),
  });

const ALL_OPERATOR_WEEKDAYS = [1, 2, 3, 4, 5, 6];

const normalizeOperatorAvailabilityRanges = (
  items?: OperatorAvailabilityRange[],
) =>
  (items ?? [])
    .map((item, index) => {
      const legacyItem = item as OperatorAvailabilityRange & {
        start_date?: string;
        end_date?: string;
      };
      return {
        id: legacyItem.id?.trim() || `operator-range-${index}`,
        startDate: (legacyItem.startDate ?? legacyItem.start_date ?? '').trim(),
        endDate: (legacyItem.endDate ?? legacyItem.end_date ?? '').trim(),
        label: legacyItem.label?.trim() ?? '',
      };
    })
    .filter(
      (item) =>
        item.startDate !== '' &&
        item.endDate !== '' &&
        item.startDate <= item.endDate,
    );

const normalizeOperatorAvailability = (
  availability?: OperatorAvailability,
): OperatorAvailability => {
  const enabledWeekdays = Array.isArray(availability?.enabledWeekdays)
    ? availability?.enabledWeekdays
        .filter(
          (item): item is number =>
            Number.isInteger(item) && item >= 0 && item <= 6,
        )
        .filter((item, index, array) => array.indexOf(item) === index)
        .sort((first, second) => first - second)
    : [];

  return {
    enabledWeekdays:
      enabledWeekdays.length > 0 ? enabledWeekdays : ALL_OPERATOR_WEEKDAYS,
    dateRanges: normalizeOperatorAvailabilityRanges(availability?.dateRanges),
  };
};

const normalizeOperatori = (items: Operatore[]) =>
  items.map((item) => ({
    ...item,
    nome: item.nome.trim(),
    mestiere: item.mestiere.trim(),
    fotoUri: item.fotoUri === undefined ? undefined : item.fotoUri?.trim() ?? '',
    availability: normalizeOperatorAvailability(item.availability),
    publicServiceMode:
      item.publicServiceMode === 'selected' ||
      item.publicServiceMode === 'all_role'
        ? item.publicServiceMode
        : undefined,
    publicServiceIds: Array.isArray(item.publicServiceIds)
      ? normalizeStringIdArray(item.publicServiceIds)
      : undefined,
    publicServiceKeys: Array.isArray(item.publicServiceKeys)
      ? normalizeStringIdArray(item.publicServiceKeys)
      : undefined,
  }));

const buildServiziSignature = (items: Servizio[]) =>
  JSON.stringify(
    normalizeServizi(items).map((item) => ({
      id: item.id,
      nome: item.nome,
      descrizione: item.descrizione ?? '',
      prezzo: item.prezzo,
      prezzoOriginale: item.prezzoOriginale ?? null,
      scontoAttivo: item.scontoAttivo ?? null,
      scontoValidoDal: item.scontoValidoDal ?? '',
      scontoValidoAl: item.scontoValidoAl ?? '',
      scontoOraDalle: item.scontoOraDalle ?? '',
      scontoOraAlle: item.scontoOraAlle ?? '',
      scontoGiorniSettimana: item.scontoGiorniSettimana ?? [],
      durataMinuti: item.durataMinuti ?? 60,
      mestiereRichiesto: item.mestiereRichiesto ?? '',
      badgeCliente: item.badgeCliente ?? '',
      ordineMestiereCliente: item.ordineMestiereCliente ?? null,
      ordineCliente: item.ordineCliente ?? null,
      disponibileOnline: item.disponibileOnline !== false,
      soloComposizione: item.soloComposizione === true,
      compositionSourceKind: item.compositionSourceKind ?? null,
      compositionSourceServiceId: item.compositionSourceServiceId ?? '',
      compositionSourcePhase: item.compositionSourcePhase ?? null,
      phaseConfig: item.phaseConfig ?? null,
      linkedServiceConfig: item.linkedServiceConfig ?? null,
      macchinarioIds: normalizeStringIdArray(item.macchinarioIds),
    })),
  );

const buildOperatoriSignature = (items: Operatore[]) =>
  JSON.stringify(
    normalizeOperatori(items).map((item) => ({
      id: item.id,
      nome: item.nome,
      mestiere: item.mestiere,
      fotoUri: item.fotoUri ?? '',
      availability: normalizeOperatorAvailability(item.availability),
      publicServiceMode: item.publicServiceMode ?? 'all_role',
      publicServiceIds: normalizeStringIdArray(item.publicServiceIds),
      publicServiceKeys: normalizeStringIdArray(item.publicServiceKeys),
    })),
  );

const buildOrderIndependentCollectionSignature = <T,>(items: T[]) =>
  JSON.stringify(items.map((item) => JSON.stringify(item)).sort());

const buildAndroidPortalRequestSignature = (
  items: RichiestaPrenotazione[],
) =>
  buildOrderIndependentCollectionSignature(
    normalizeRichiestePrenotazione(items).map(
      ({ mestiereRichiesto: _derivedRole, ...item }) => item,
    ),
  );

type Macchinario = {
  id: string;
  nome: string;
  mestiereRichiesto?: string;
  categoria: string;
  note?: string;
  attivo?: boolean;
};

const normalizeMacchinari = (items: Macchinario[]) =>
  items.map((item) => ({
    ...item,
    nome: item.nome.trim(),
    mestiereRichiesto: item.mestiereRichiesto?.trim() ?? '',
    categoria: item.categoria.trim(),
    note: item.note?.trim() ?? '',
    attivo: item.attivo ?? true,
  }));

type OwnerAppSnapshotPayload = {
  workspace?: Partial<SalonWorkspace>;
  clienti?: Cliente[];
  appuntamenti?: Appuntamento[];
  movimenti?: Movimento[];
  servizi?: Servizio[];
  operatori?: Operatore[];
  operatoriArchiviati?: Operatore[];
  macchinari?: Macchinario[];
  carteCollegate?: CartaCollegata[];
  eventi?: Evento[];
  richiestePrenotazione?: RichiestaPrenotazione[];
  availabilitySettings?: AvailabilitySettings;
  messaggioEventoTemplate?: string;
  serviceCardColorOverrides?: Record<string, string>;
  roleCardColorOverrides?: Record<string, string>;
};

const sanitizeWorkspaceForDerivedSnapshots = (
  workspace: Partial<SalonWorkspace> | null | undefined,
): Partial<SalonWorkspace> | undefined => {
  if (!workspace) {
    return undefined;
  }

  const {
    customerReminderHoursBefore: _customerReminderHoursBefore,
    ...restWorkspace
  } = workspace;

  return restWorkspace;
};

const normalizeOwnerAppSnapshotPayload = (
  payload: Record<string, unknown> | null | undefined,
): OwnerAppSnapshotPayload | null => {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    return null;
  }

  return {
    workspace:
      payload.workspace &&
      typeof payload.workspace === 'object' &&
      !Array.isArray(payload.workspace)
        ? sanitizeWorkspaceForDerivedSnapshots(
            payload.workspace as Partial<SalonWorkspace>,
          )
        : undefined,
    clienti: Array.isArray(payload.clienti)
      ? normalizeClienti(payload.clienti as Cliente[])
      : undefined,
    appuntamenti: Array.isArray(payload.appuntamenti)
      ? normalizeAppuntamenti(payload.appuntamenti as Appuntamento[])
      : undefined,
    movimenti: Array.isArray(payload.movimenti)
      ? normalizeMovimenti(payload.movimenti as Movimento[])
      : undefined,
    servizi: Array.isArray(payload.servizi)
      ? normalizeServizi(payload.servizi as Servizio[])
      : undefined,
    operatori: Array.isArray(payload.operatori)
      ? normalizeOperatori(payload.operatori as Operatore[])
      : undefined,
    operatoriArchiviati: Array.isArray(payload.operatoriArchiviati)
      ? normalizeOperatori(payload.operatoriArchiviati as Operatore[])
      : undefined,
    macchinari: Array.isArray(payload.macchinari)
      ? normalizeMacchinari(payload.macchinari as Macchinario[])
      : undefined,
    carteCollegate: Array.isArray(payload.carteCollegate)
      ? normalizeCarte(payload.carteCollegate as CartaCollegata[])
      : undefined,
    eventi: Array.isArray(payload.eventi)
      ? normalizeEventi(payload.eventi as Evento[])
      : undefined,
    richiestePrenotazione: Array.isArray(payload.richiestePrenotazione)
      ? normalizeRichiestePrenotazione(
          payload.richiestePrenotazione as RichiestaPrenotazione[],
        )
      : undefined,
    availabilitySettings:
      payload.availabilitySettings &&
      typeof payload.availabilitySettings === 'object'
        ? normalizeAvailabilitySettings(
            payload.availabilitySettings as AvailabilitySettings,
          )
        : undefined,
    messaggioEventoTemplate:
      typeof payload.messaggioEventoTemplate === 'string'
        ? payload.messaggioEventoTemplate
        : undefined,
    serviceCardColorOverrides:
      payload.serviceCardColorOverrides &&
      typeof payload.serviceCardColorOverrides === 'object'
        ? normalizeServiceColorOverrideMap(
            payload.serviceCardColorOverrides as Record<string, string>,
            Array.isArray(payload.servizi)
              ? normalizeServizi(payload.servizi as Servizio[])
              : [],
          )
        : undefined,
    roleCardColorOverrides:
      payload.roleCardColorOverrides &&
      typeof payload.roleCardColorOverrides === 'object'
        ? normalizeRoleColorOverrideMap(
            payload.roleCardColorOverrides as Record<string, string>,
          )
        : undefined,
  };
};

const hasCompleteOwnerServerBackup = (
  payload: OwnerAppSnapshotPayload | null | undefined,
) =>
  !!payload &&
  payload.workspace !== undefined &&
  payload.clienti !== undefined &&
  payload.appuntamenti !== undefined &&
  payload.movimenti !== undefined &&
  payload.servizi !== undefined &&
  payload.operatori !== undefined &&
  payload.macchinari !== undefined &&
  payload.carteCollegate !== undefined &&
  payload.eventi !== undefined &&
  payload.richiestePrenotazione !== undefined &&
  payload.availabilitySettings !== undefined &&
  payload.messaggioEventoTemplate !== undefined &&
  payload.serviceCardColorOverrides !== undefined &&
  payload.roleCardColorOverrides !== undefined;

const buildOwnerPrivateServerStateFromSnapshot = (
  ownerSnapshot: OwnerAppSnapshotPayload | null,
) => ({
  ownerSnapshot,
  appuntamenti: ownerSnapshot?.appuntamenti ?? normalizeAppuntamenti([]),
  servizi: ownerSnapshot?.servizi ?? normalizeServizi([]),
  operatori: ownerSnapshot?.operatori ?? normalizeOperatori([]),
  operatoriArchiviati:
    ownerSnapshot?.operatoriArchiviati ?? normalizeOperatori([]),
  macchinari: ownerSnapshot?.macchinari ?? normalizeMacchinari([]),
  availabilitySettings:
    ownerSnapshot?.availabilitySettings ?? normalizeAvailabilitySettings(),
  clienti: ownerSnapshot?.clienti ?? normalizeClienti([]),
  richiestePrenotazione:
    ownerSnapshot?.richiestePrenotazione ?? normalizeRichiestePrenotazione([]),
  movimenti: ownerSnapshot?.movimenti ?? normalizeMovimenti([]),
  carteCollegate: ownerSnapshot?.carteCollegate ?? normalizeCarte([]),
  eventi: ownerSnapshot?.eventi ?? normalizeEventi([]),
  messaggioEventoTemplate: ownerSnapshot?.messaggioEventoTemplate ?? '',
});

const movementMethodToRemote = (
  value?: Movimento['metodo'],
): 'cash' | 'card' | 'bank_transfer' | null => {
  if (value === 'Contanti') return 'cash';
  if (value === 'Carta') return 'card';
  if (value === 'Bonifico') return 'bank_transfer';
  return null;
};

const movementMethodFromRemote = (
  value?: string | null,
): Movimento['metodo'] | undefined => {
  if (value === 'cash') return 'Contanti';
  if (value === 'card') return 'Carta';
  if (value === 'bank_transfer') return 'Bonifico';
  return undefined;
};

const buildMovementSemanticKey = (
  item: Pick<Movimento, 'descrizione' | 'importo' | 'createdAt'>,
) =>
  [
    item.descrizione.trim().toLowerCase(),
    item.importo.toFixed(2),
    deriveMovementCreatedAt(item as Movimento),
  ].join('|');

const buildCardSemanticKey = (
  item: Pick<CartaCollegata, 'nome' | 'circuito' | 'ultime4'>,
) =>
  [
    item.nome.trim().toLowerCase(),
    item.circuito.trim().toLowerCase(),
    item.ultime4.trim(),
  ].join('|');

const buildEventSemanticKey = (item: Pick<Evento, 'titolo' | 'data' | 'ora'>) =>
  [item.titolo.trim().toLowerCase(), item.data.trim(), item.ora.trim()].join(
    '|',
  );

