  const registerPendingConfirmedCompositionGroup = React.useCallback(
    (groupKey: string, appointments: Appuntamento[]) => {
      const normalizedAppointments = normalizeAppuntamenti(appointments);
      if (normalizedAppointments.length < 2) {
        return;
      }

      const normalizedGroupKey = groupKey.trim();
      if (!normalizedGroupKey) {
        return;
      }

      pendingConfirmedCompositionGroupsRef.current.set(normalizedGroupKey, {
        createdAt: Date.now(),
        appointments: normalizedAppointments,
        authoritativeAcknowledged: false,
        portalAcknowledged: false,
      });
    },
    [],
  );

  const getPendingConfirmedCompositionPreserveOptions = React.useCallback(
    (remoteItems: Appuntamento[], options?: { authoritative?: boolean }) => {
      const normalizedRemoteItems = normalizeAppuntamenti(remoteItems);
      const remoteIds = new Set(
        normalizedRemoteItems
          .filter((item) => isUuidValue(item.id))
          .map((item) => item.id),
      );
      const remoteCompositeKeys = new Set(
        normalizedRemoteItems.map((item) => buildAppuntamentoMergeKey(item)),
      );
      const preserveLocalCompositeKeys = new Set<string>();
      const preserveLocalIds = new Set<string>();
      const pendingAppointments: Appuntamento[] = [];
      const now = Date.now();

      pendingConfirmedCompositionGroupsRef.current.forEach(
        (pendingGroup, groupKey) => {
          if (
            now - pendingGroup.createdAt >
            PENDING_CONFIRMED_COMPOSITION_GUARD_MS
          ) {
            pendingConfirmedCompositionGroupsRef.current.delete(groupKey);
            return;
          }

          const isFullyAcknowledged = pendingGroup.appointments.every(
            (appointment) =>
              isUuidValue(appointment.id)
                ? remoteIds.has(appointment.id)
                : remoteCompositeKeys.has(
                    buildAppuntamentoMergeKey(appointment),
                  ),
          );

          if (isFullyAcknowledged) {
            const nextPendingGroup = {
              ...pendingGroup,
              authoritativeAcknowledged:
                pendingGroup.authoritativeAcknowledged ||
                options?.authoritative !== false,
              portalAcknowledged:
                pendingGroup.portalAcknowledged ||
                options?.authoritative === false,
            };
            if (
              nextPendingGroup.authoritativeAcknowledged &&
              nextPendingGroup.portalAcknowledged
            ) {
              pendingConfirmedCompositionGroupsRef.current.delete(groupKey);
            } else {
              pendingConfirmedCompositionGroupsRef.current.set(
                groupKey,
                nextPendingGroup,
              );
            }
            return;
          }

          pendingGroup.appointments.forEach((appointment) => {
            preserveLocalIds.add(appointment.id);
            preserveLocalCompositeKeys.add(
              buildAppuntamentoMergeKey(appointment),
            );
            pendingAppointments.push(appointment);
          });
        },
      );

      return {
        preserveLocalCompositeKeys,
        preserveLocalIds,
        pendingAppointments: normalizeAppuntamenti(pendingAppointments),
      };
    },
    [],
  );

