              normalizeAccountEmail(savedOwnerSession) ||
              normalizeAccountEmail(savedActiveAccount);
            const allowSilentSessionRecovery =
              Platform.OS === 'web' ||
              isAuthenticated ||
              pendingBiometricUnlockRef.current;
            const shouldAttemptRecovery =
              explicitLogoutSaved !== 'true' &&
              !ownerExplicitLogoutRef.current &&
              !!persistedEmail &&
              Platform.OS !== 'web' &&
              allowSilentSessionRecovery;

            if (shouldAttemptRecovery) {
              setOwnerAuthRecoveryPending(true);
              await waitMs(500);
              const { data: retriedSessionResult } =
                await getSupabaseSessionSafely();
              const recoveredEmail = normalizeAccountEmail(
                retriedSessionResult.session?.user?.email,
              );

              if (ownerAuthStateEventSeqRef.current !== eventSeq) {
                return;
              }

              if (recoveredEmail) {
                AsyncStorage.setItem(
                  STORAGE_KEYS.owner_session,
                  recoveredEmail,
                ).catch(() => undefined);
                AsyncStorage.setItem(
                  STORAGE_KEYS.account_attivo,
                  recoveredEmail,
                ).catch(() => undefined);
                AsyncStorage.removeItem(
                  STORAGE_KEYS.owner_explicit_logout,
                ).catch(() => undefined);
                ownerAuthSessionRecoveryInFlightRef.current = false;
                setOwnerAuthRecoveryPending(false);
                setOwnerExplicitLogout(false);
                setSalonAccountEmail(recoveredEmail);
                setIsAuthenticated(true);
                setIsLoaded(true);
                void (async () => {
                  await prepareOnboardingStateForAuthenticatedAccountRef.current(
                    recoveredEmail,
                  );
                  await syncAuthenticatedWorkspaceRef.current(
                    recoveredEmail,
                    true,
                  );
                })();
                return;
              }

              const fallbackRecoveryEmail =
                normalizeAccountEmail(salonAccountEmail) || persistedEmail;
              if (fallbackRecoveryEmail) {
                setOwnerExplicitLogout(false);
                setSalonAccountEmail(
                  (current) => current || fallbackRecoveryEmail,
                );
                await waitMs(1400);
                const { data: secondSessionResult } =
                  await getSupabaseSessionSafely();
                const secondRecoveredEmail = normalizeAccountEmail(
                  secondSessionResult.session?.user?.email,
                );

                if (ownerAuthStateEventSeqRef.current !== eventSeq) {
                  return;
                }

                if (secondRecoveredEmail) {
                  AsyncStorage.setItem(
                    STORAGE_KEYS.owner_session,
                    secondRecoveredEmail,
                  ).catch(() => undefined);
                  AsyncStorage.setItem(
                    STORAGE_KEYS.account_attivo,
                    secondRecoveredEmail,
                  ).catch(() => undefined);
                  AsyncStorage.removeItem(
                    STORAGE_KEYS.owner_explicit_logout,
                  ).catch(() => undefined);
                  ownerAuthSessionRecoveryInFlightRef.current = false;
                  setOwnerAuthRecoveryPending(false);
                  setOwnerExplicitLogout(false);
                  setSalonAccountEmail(secondRecoveredEmail);
                  setIsAuthenticated(true);
                  setIsLoaded(true);
                  void (async () => {
                    await prepareOnboardingStateForAuthenticatedAccountRef.current(
                      secondRecoveredEmail,
                    );
                    await syncAuthenticatedWorkspaceRef.current(
                      secondRecoveredEmail,
                      true,
                    );
                  })();
                  return;
                }
              }
            }

            AsyncStorage.removeItem(STORAGE_KEYS.owner_session).catch(
              () => undefined,
            );
